local TrailStagePopupShow = Class("TrailStagePopupShow")
function TrailStagePopupShow:__init()

end

function TrailStagePopupShow:__delete()
    self.controller = nil
end

function TrailStagePopupShow:Awake()
    SetButtonAction(self.FontStyleButton, function ()
        UIModule.BackDialog()
    end)
    local trailBattleMgr = TrailBattleMgr:GetInstance()
    local argument = self.controller.Argument.parameters
    if argument and argument.type then
        local segment = checkNumber(trailBattleMgr:GetMySegment())
        local segmentVo = trailBattleMgr:GetSegmentRewardVoByRefId(segment)
        self.ImgLevel.Status = segmentVo.icon
        self.TxtState.text = segmentVo.name
        local enterData = trailBattleMgr:GetEnterData()
        if argument.type == TrailBattleMgr.CONSTANTS.POPUP_TYPE.FIRST_ENTRY then
            KTool.SetActive(self.TextDescribe.transform, false)
            self.TxtTitle.Status = titleSwitchText.FirstLanding
            --self.TxtTitle.text = localize("由于初次进入，调查官本期被划分在")
            --self.TxtState.text = segmentVo.name
            --self.TxtState.text = string.format(localize("用于初次进入，调查官本期被划分在<color=#ffdc70>[%s]</color>\n挑战关卡获得积分获得晋级机会，赢取丰富奖励"), segmentVo.name)
        elseif argument.type == TrailBattleMgr.CONSTANTS.POPUP_TYPE.SEGMENT_CHANGE then
            --local segment, lastSegment = argument.segment, argument.lastSegment
            --local segmentVo = trailBattleMgr:GetSegmentRewardVoByRefId(segment)
            KTool.SetActive(self.TextDescribe.transform, true)
            self.TextDescribe.text = string.format("上轮获得组内第%s名", enterData.lastRank)

            --self.TxtTitle.text = localize('根据上一期的排名，调查官本期被划分在')
            --self.TxtState.text = segmentVo.name
            --self.TxtState.text = string.format(localize("根据上一期的排名，调查官本期被划分在<color=#ffdc70>[%s]</color>\n挑战关卡获得积分获得晋级机会，赢取丰富奖励"), segmentVo.name)
            local lastSegment = checkNumber(enterData.lastSegment)
            if segment > lastSegment then--晋级
                self.TxtTitle.Status = titleSwitchText.UpGrade
                CfUtils.SetUISwitchText(self.TextDescribe.transform, 2)
                KTool.SetActive(self.ParticleUp, true)
                self.animName = "Up"
            elseif segment == lastSegment then --保级
                self.TxtTitle.Status = titleSwitchText.KeepGrade
                CfUtils.SetUISwitchText(self.TextDescribe.transform, 1)
                KTool.SetActive(self.ParticleKeep, true)
                self.animName = "Keep"
            else --降级
                self.TxtTitle.Status = titleSwitchText.DownGrade
                CfUtils.SetUISwitchText(self.TextDescribe.transform, 1)
                KTool.SetActive(self.ParticleDown, true)
                self.animName = "Down"
            end
        elseif argument.type == TrailBattleMgr.CONSTANTS.POPUP_TYPE.MANY_SEASON_NOT_JOIN then
            KTool.SetActive(self.TextDescribe.transform, false)
            self.TxtTitle.Status = titleSwitchText.CurrentGrade
        end

    end
end

function TrailStagePopupShow:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self.animName then
            self.AnimNode:Play(self.animName)
        end
    end))
    return coWait
end

